// Per-account profile over the Reg M-C stores (worktree-tracked .gz), crossed with the live ladders.
'use strict';
const fs = require('fs'), path = require('path'), zlib = require('zlib'), readline = require('readline');
const WT = 'C:/Users/willj/Projects/Pokemon/ABRA/.claude/worktrees/agent-a992c7df2135eaf4a';
const S = __dirname;
const toID = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
async function profile(fmt) {
  const f = path.join(WT, 'data', 'games.' + fmt + '.jsonl.gz');
  const acc = new Map(); const seen = new Set(); let n = 0;
  const rl = readline.createInterface({ input: fs.createReadStream(f).pipe(zlib.createGunzip()), crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue; let g; try { g = JSON.parse(line); } catch (e) { continue; }
    if (seen.has(g.id)) continue; seen.add(g.id); n++;
    const day = String(g.date || '').slice(0, 10);
    for (const s of ['p1', 'p2']) {
      const p = g[s] || {}; if (!p.name) continue;
      let a = acc.get(p.name); if (!a) acc.set(p.name, a = { name: p.name, games: 0, teams: new Map(), days: new Map(), maxr: 0, ff: 0, botflag: false, sheet: 0 });
      a.games++; a.days.set(day, (a.days.get(day) || 0) + 1);
      const six = ((g.six || {})[s] || []).slice().sort().join('|'); if (six) a.teams.set(six, (a.teams.get(six) || 0) + 1);
      if (p.rating > a.maxr) a.maxr = p.rating; if (p.bot) a.botflag = true;
      if (g.forfeit && g.winner && g.winner !== p.name) a.ff++;
    }
  }
  const lad = JSON.parse(fs.readFileSync(path.join(S, 'ladder-' + fmt + '.json'), 'utf8')).toplist;
  const rank = new Map(lad.map((u, i) => [u.userid, { rank: i + 1, elo: Math.round(u.elo), wl: u.w + u.l }]));
  const rows = [...acc.values()].map(a => {
    const top = Math.max(0, ...a.teams.values());
    return { name: a.name, games: a.games, teams: a.teams.size, topShare: +(top / a.games).toFixed(3), days: a.days.size,
      perDay: +(a.games / a.days.size).toFixed(1), maxDay: Math.max(...a.days.values()), maxr: a.maxr, ffLoss: +(a.ff / a.games).toFixed(3),
      botflag: a.botflag, ladder: rank.get(toID(a.name)) || null };
  });
  return { fmt, file: path.relative(WT, f), bytes: fs.statSync(f).size, games: n, accounts: rows.length, rows };
}
(async () => {
  const out = {};
  for (const fmt of ['gen9championsvgc2026regmc', 'gen9championsvgc2026regmcbo3']) out[fmt] = await profile(fmt);
  fs.writeFileSync(path.join(S, 'bots-profile.json'), JSON.stringify(out));
  for (const [fmt, P] of Object.entries(out)) {
    console.log(`\n== ${fmt}  ${P.games} games  ${P.accounts} accounts`);
    const big = P.rows.filter(r => r.games >= 30).sort((a, b) => a.teams - b.teams || b.games - a.games);
    console.log('one-team accounts >=30 games:');
    for (const r of big.filter(r => r.teams === 1)) console.log(`  ${r.name.padEnd(22)} g=${r.games} days=${r.days} perDay=${r.perDay} maxDay=${r.maxDay} maxr=${r.maxr} ffLoss=${r.ffLoss} bot=${r.botflag} ladder=${r.ladder ? JSON.stringify(r.ladder) : '-'}`);
    // distribution of perDay and maxDay for multi-team accounts >= 50 games
    const multi = P.rows.filter(r => r.games >= 50 && r.teams > 1);
    const q = (arr, p) => { const s = arr.slice().sort((a, b) => a - b); return s[Math.floor(p * (s.length - 1))]; };
    console.log(`multi-team >=50 games: ${multi.length}; perDay p50 ${q(multi.map(r => r.perDay), .5)} p90 ${q(multi.map(r => r.perDay), .9)} max ${Math.max(...multi.map(r => r.perDay))}; maxDay p90 ${q(multi.map(r => r.maxDay), .9)} max ${Math.max(...multi.map(r => r.maxDay))}`);
    const hi = multi.sort((a, b) => b.maxDay - a.maxDay).slice(0, 8);
    for (const r of hi) console.log(`   multi ${r.name.padEnd(22)} g=${r.games} teams=${r.teams} top=${r.topShare} perDay=${r.perDay} maxDay=${r.maxDay} maxr=${r.maxr} ladder=${r.ladder ? r.ladder.rank : '-'}`);
    // top-share distribution among >=50 multi-team
    console.log(`   topShare>=0.9 among multi>=50: ${multi.filter(r => r.topShare >= 0.9).length}`);
  }
})();

