// Before/after of the three quality changes on each Reg M-C store, through engine/quality.js itself.
// Run with ABRA_NO_STORE_CACHE=1 so the two bot sets are not served from one memo.
'use strict';
const path = require('path');
const WT = 'C:/Users/willj/Projects/Pokemon/ABRA/.claude/worktrees/agent-a992c7df2135eaf4a';
const Q = require(path.join(WT, 'engine', 'quality.js'));
const cfg = Q.config();
const cfgOld = JSON.parse(JSON.stringify(cfg));
delete cfgOld.rules.exclude_behavioural_bots.min_games_in_one_day;
delete cfgOld.rules.exclude_behavioural_bots.tempo_applies_id_pattern;
const out = {};
const stores = ['gen9championsvgc2026regmcbo3', 'gen9championsvgc2026regmc'].map(f => path.join(WT, 'data', 'games.' + f + '.jsonl'));
const all = [];
for (const s of stores) all.push(...Q.readStore(s));
const botsNewAll = Q.behaviouralBots(all, cfg), botsOldAll = Q.behaviouralBots(all, cfgOld);
for (const s of stores) {
  const games = Q.readStore(s);
  const res = {};
  for (const [label, bots] of [['per_store', null], ['both_stores', null]]) {
    const bNew = label === 'per_store' ? Q.behaviouralBots(games, cfg) : botsNewAll;
    const bOld = label === 'per_store' ? Q.behaviouralBots(games, cfgOld) : botsOldAll;
    let cleanOld = 0, cleanNew = 0; const only = {}; const any = {};
    for (const g of games) {
      const rNew = Q.reasons(g, cfg, bNew);
      const rOld = Q.reasons(g, cfg, bOld).filter(x => x !== 'illegal_team' && x !== 'custom_ruleset');
      if (!rOld.length) cleanOld++;
      if (!rNew.length) cleanNew++;
      for (const x of rNew) any[x] = (any[x] || 0) + 1;
      if (rNew.length === 1) only[rNew[0]] = (only[rNew[0]] || 0) + 1;
    }
    const oldBotGames = games.filter(g => [g.p1, g.p2].some(p => p && bOld.has(p.name))).length;
    const newBotGames = games.filter(g => [g.p1, g.p2].some(p => p && bNew.has(p.name))).length;
    res[label] = { games: games.length, clean_before: cleanOld, clean_after: cleanNew, bots_before: [...bOld].sort(), bots_after: [...bNew].sort(),
      behavioural_bot_games_before: oldBotGames, behavioural_bot_games_after: newBotGames, only_reason_after: only, any_reason_after: any };
  }
  out[path.basename(s)] = res;
}
console.log(JSON.stringify(out, null, 1));

