// Marginal removals of the two regulation-aware rules, on the full store and inside usage_regulation's pool predicate.
'use strict';
const path = require('path');
const WT = 'C:/Users/willj/Projects/Pokemon/ABRA/.claude/worktrees/agent-a992c7df2135eaf4a';
const Q = require(path.join(WT, 'engine', 'quality.js'));
const cfg = Q.config();
const stores = ['gen9championsvgc2026regmcbo3', 'gen9championsvgc2026regmc'].map(f => path.join(WT, 'data', 'games.' + f + '.jsonl'));
const per = stores.map(s => Q.readStore(s));
const bots = Q.behaviouralBots([].concat(...per), cfg);
for (let i = 0; i < stores.length; i++) {
  const t = { only_illegal: 0, only_custom: 0, only_both: 0, illegal_any: 0, custom_any: 0, sheets_both: 0, sheets_both_removed_by_new: 0 };
  for (const g of per[i]) {
    const rs = Q.reasons(g, cfg, bots);
    const other = rs.filter(x => x !== 'illegal_team' && x !== 'custom_ruleset');
    const hasI = rs.includes('illegal_team'), hasC = rs.includes('custom_ruleset');
    if (hasI) t.illegal_any++; if (hasC) t.custom_any++;
    if (!other.length && (hasI || hasC)) { if (hasI && hasC) t.only_both++; else if (hasI) t.only_illegal++; else t.only_custom++; }
    const sh = g.openSheet && g.sheets && (g.sheets.p1 || []).length && (g.sheets.p2 || []).length;
    if (sh) { t.sheets_both++; if (!other.length && (hasI || hasC)) t.sheets_both_removed_by_new++; }
  }
  console.log(path.basename(stores[i]), per[i].length, JSON.stringify(t));
}

