const tn = view(usage(newC, { humansOnly: true })).threats, to = view(usage(oldC, { humansOnly: true })).threats;
const om = Object.fromEntries(to.map(t => [t.sp, t]));
console.log('pool', pool.length, 'competitive old rules', oldC.length, 'new rules', newC.length);
const d = tn.map(t => [t.sp, om[t.sp] ? om[t.sp].teamRate : 0, t.teamRate, +(t.teamRate - (om[t.sp] ? om[t.sp].teamRate : 0)).toFixed(4)]);
d.sort((a, b) => Math.abs(b[3]) - Math.abs(a[3]));
console.log('largest teamRate moves:'); for (const x of d.slice(0, 8)) console.log('  ', x.join('  '));
console.log('top 10 order old:', to.slice(0, 10).map(t => t.sp).join(','));
console.log('top 10 order new:', tn.slice(0, 10).map(t => t.sp).join(','));

