// Is every game id in the stale plain Reg M-C snapshot also in the tracked .gz? (The deletion question.)
'use strict';
const fs = require('fs'), zlib = require('zlib'), readline = require('readline');
const M = 'C:/Users/willj/Projects/Pokemon/ABRA/data/';
async function ids(file, gz) {
  const s = new Set(); const inp = fs.createReadStream(file);
  const rl = readline.createInterface({ input: gz ? inp.pipe(zlib.createGunzip()) : inp, crlfDelay: Infinity });
  for await (const l of rl) { const m = l.match(/^\{"id":"([^"]+)"/); if (m) s.add(Buffer.from(m[1]).toString()); }
  return s;
}
(async () => {
  for (const f of ['games.gen9championsvgc2026regmc.jsonl', 'games.gen9championsvgc2026regmcbo3.jsonl']) {
    const p = await ids(M + f, false), g = await ids(M + f + '.gz', true);
    let missing = 0; for (const id of p) if (!g.has(id)) missing++;
    console.log(f, 'plain', p.size, 'gz', g.size, 'plain ids absent from gz', missing, 'gz mtime', fs.statSync(M + f + '.gz').mtime.toISOString());
  }
})();

