// Builds data/verification/2026-09-30-regmc-store-quality.json from this pass's measurement outputs,
// re-running the marginal-removal and rule-effect counts in-process. Run with ABRA_REGULATION=regmc.
'use strict';
process.env.ABRA_NO_STORE_CACHE = '1';
const fs = require('fs'), path = require('path');
const S = __dirname;
const WT = 'C:/Users/willj/Projects/Pokemon/ABRA/.claude/worktrees/agent-a992c7df2135eaf4a';
const REGN = require(path.join(WT, 'engine', 'regulation.js'));
const Q = require(path.join(WT, 'engine', 'quality.js'));
const DI = require(path.join(WT, 'engine', 'durable-ingest.js'));
const PRED = require(path.join(WT, 'engine', 'regmc_pool_predicate.js'));
const { usage, view } = require(path.join(WT, 'engine', 'usage_table.js'));
const cfg = Q.config();
const cfgOld = JSON.parse(JSON.stringify(cfg));
delete cfgOld.rules.exclude_behavioural_bots.min_games_in_one_day;
delete cfgOld.rules.exclude_behavioural_bots.tempo_applies_id_pattern;
const files = [REGN.BO3_FORMAT, REGN.FORMAT].map(f => path.join(WT, 'data', 'games.' + f + '.jsonl.gz'));
const per = files.map(f => Q.readStore(f));
const all = [].concat(...per);
const bNewAll = Q.behaviouralBots(all, cfg), bOldAll = Q.behaviouralBots(all, cfgOld);

const stores = {};
files.forEach((f, i) => {
  const games = per[i];
  const bNew = Q.behaviouralBots(games, cfg), bOld = Q.behaviouralBots(games, cfgOld);
  let cleanOld = 0, cleanNew = 0;
  const m = { illegal_team_flagged: 0, custom_ruleset_flagged: 0, removed_only_by_these_two: 0, removed_illegal_only: 0, removed_custom_only: 0, removed_both: 0 };
  for (const g of games) {
    const rNew = Q.reasons(g, cfg, bNew);
    const other = rNew.filter(x => x !== 'illegal_team' && x !== 'custom_ruleset');
    const rOld = Q.reasons(g, cfg, bOld).filter(x => x !== 'illegal_team' && x !== 'custom_ruleset');
    if (!rOld.length) cleanOld++;
    if (!rNew.length) cleanNew++;
    const hi = rNew.includes('illegal_team'), hc = rNew.includes('custom_ruleset');
    if (hi) m.illegal_team_flagged++; if (hc) m.custom_ruleset_flagged++;
    if (!other.length && (hi || hc)) { m.removed_only_by_these_two++; if (hi && hc) m.removed_both++; else if (hi) m.removed_illegal_only++; else m.removed_custom_only++; }
  }
  const touched = b => games.filter(g => [g.p1, g.p2].some(p => p && b.has(p.name))).length;
  stores[path.basename(f)] = {
    games: games.length,
    per_store_loadGames: { clean_old_rules: cleanOld, clean_new_rules: cleanNew, bots_old: [...bOld].sort(), bots_new: [...bNew].sort(),
      games_touched_by_behavioural_bot_old: touched(bOld), games_touched_by_behavioural_bot_new: touched(bNew) },
    two_id_keyed_rules: m,
  };
});

const TOKEN = DI.storeFormatFor({ label: REGN.LABEL, showdownFormat: REGN.FORMAT }, 'runtime.regmc');
const pool = all.filter(g => g.format === TOKEN && PRED.inScope(g) && !PRED.oldRule(g));
const newC = pool.filter(g => !Q.reasons(g, cfg, bNewAll).length);
const oldC = pool.filter(g => !Q.reasons(g, cfg, bOldAll).filter(x => x !== 'illegal_team' && x !== 'custom_ruleset').length);
const tn = view(usage(newC, { humansOnly: true })).threats, to = view(usage(oldC, { humansOnly: true })).threats;
const om = Object.fromEntries(to.map(t => [t.sp, t.teamRate]));
const moves = tn.map(t => ({ sp: t.sp, old: om[t.sp] || 0, new: t.teamRate, delta: +(t.teamRate - (om[t.sp] || 0)).toFixed(4) }))
  .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta)).slice(0, 8);
const before = JSON.parse(fs.readFileSync(path.join(S, 'meta-usage-regmc.before.json'), 'utf8'));

const prof = JSON.parse(fs.readFileSync(path.join(S, 'bots-profile.json'), 'utf8'));
const oneTeam = {};
for (const [fmt, P] of Object.entries(prof)) oneTeam[fmt] = P.rows.filter(r => r.teams === 1 && r.games >= 50).sort((a, b) => b.maxDay - a.maxDay);
const ladders = {};
for (const fmt of [REGN.FORMAT, REGN.BO3_FORMAT]) {
  const f = path.join(S, 'ladder-' + fmt + '.json');
  ladders[fmt] = { url: 'https://pokemonshowdown.com/ladder/' + fmt + '.json', fetched_mtime: fs.statSync(f).mtime.toISOString(), listed: JSON.parse(fs.readFileSync(f, 'utf8')).toplist.length };
}

const out = {
  by: 'MEASURE, abra/regmc 1.36.0 (scratch builder embedded below)',
  generated: new Date().toISOString(),
  report: 'docs/_reports/2026-09-30-regmc-store-quality.md',
  stores_read: files.map(f => path.relative(WT, f).split(path.sep).join('/')),
  store_blobs: { 'data/games.gen9championsvgc2026regmc.jsonl.gz': '76ef2de7', 'data/games.gen9championsvgc2026regmcbo3.jsonl.gz': 'd2b5041a' },
  rule_old: 'min_games 50, max_distinct_teams 1, no id-keyed Reg M-C verdict',
  rule_new: 'the same plus min_games_in_one_day ' + cfg.rules.exclude_behavioural_bots.min_games_in_one_day + ' for ids matching ' + cfg.rules.exclude_behavioural_bots.tempo_applies_id_pattern + ', plus data/store-validation-regmc.json and data/custom-ruleset-ids-regmc.json',
  stores,
  usage_competitive_view_same_stores: { pool_after_predicate: pool.length, competitive_old_rules: oldC.length, competitive_new_rules: newC.length,
    top10_old: to.slice(0, 10).map(t => t.sp), top10_new: tn.slice(0, 10).map(t => t.sp), largest_teamRate_moves: moves },
  meta_usage_regmc_before: { generated_at: before.generated_at, usable: before.provenance.usable, stores: before.provenance.stores.map(s => ({ file: s.file, unique_games: s.unique_games, sha256: s.sha256 })) },
  one_team_accounts_ge50_games: oneTeam,
  live_ladders: ladders,
  scripts: Object.fromEntries(['bots.js', 'funnel.js', 'marg.js', 'ruleeffect.js', 'subset.js', 'build_verif.js'].map(n => [n, fs.readFileSync(path.join(S, n), 'utf8')])),
};
const dest = path.join(WT, 'data', 'verification', '2026-09-30-regmc-store-quality.json');
fs.writeFileSync(dest, JSON.stringify(out, null, 1) + '\n');
console.log('wrote', dest);
for (const [k, v] of Object.entries(stores)) console.log(k, JSON.stringify(v.per_store_loadGames.clean_old_rules), '->', v.per_store_loadGames.clean_new_rules, JSON.stringify(v.two_id_keyed_rules));
console.log(JSON.stringify(out.usage_competitive_view_same_stores).slice(0, 400));
